function initDropZones(){const containers=document.querySelectorAll('.file-drop-container');containers.forEach(container=>{const dropZone=container.querySelector('.dropZone');const fileInput=container.querySelector('input[type="file"]');const dropZonePrompt=container.querySelector('.dropZonePrompt');const filePreview=container.querySelector('.filePreview');const fileName=container.querySelector('.fileName');const fileSize=container.querySelector('.fileSize');const removeFileBtn=container.querySelector('.removeFileBtn');const fileError=container.querySelector('.fileError');if(!dropZone||!fileInput)return;dropZone.onclick=(e)=>{if(e.target.closest('.removeFileBtn'))return;fileInput.click();};fileInput.onchange=()=>{if(fileInput.files.length>0){handleFile(fileInput.files[0]);}};['dragenter','dragover','dragleave','drop'].forEach(eventName=>{dropZone.addEventListener(eventName,e=>{e.preventDefault();e.stopPropagation();},false);});['dragenter','dragover'].forEach(eventName=>{dropZone.addEventListener(eventName,()=>dropZone.classList.add('border-[#b61615]','bg-red-50/50'),false);});['dragleave','drop'].forEach(eventName=>{dropZone.addEventListener(eventName,()=>dropZone.classList.remove('border-[#b61615]','bg-red-50/50'),false);});dropZone.ondrop=(e)=>{const files=e.dataTransfer.files;if(files.length>0){fileInput.files=files;handleFile(files[0]);}};function handleFile(file){if(fileError)fileError.classList.add('hidden');const validTypes=['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document'];if(!validTypes.includes(file.type)){if(fileError){fileError.textContent='Please select a valid PDF or Word document.';fileError.classList.remove('hidden');}return;}if(fileName)fileName.textContent=file.name;if(fileSize)fileSize.textContent=(file.size/(1024*1024)).toFixed(2)+' MB';if(dropZonePrompt)dropZonePrompt.classList.add('hidden');if(filePreview)filePreview.classList.remove('hidden');}if(removeFileBtn){removeFileBtn.onclick=(e)=>{e.stopPropagation();fileInput.value='';if(filePreview)filePreview.classList.add('hidden');if(dropZonePrompt)dropZonePrompt.classList.remove('hidden');if(fileError)fileError.classList.add('hidden');};}});}document.addEventListener('DOMContentLoaded',initDropZones);document.addEventListener('htmx:afterSettle',initDropZones);;